from pathlib import Path

p=Path('installer-v2/launcher/csm_fiscal_core.cs')
s=p.read_text(encoding='utf-8')
MARK='CSM_FISCAL_CORE_SOAP_3121'
if MARK in s:
    print('Fiscal Core SOAP 3.12.1 já aplicado')
    raise SystemExit(0)

# 1) Consulta Protocolo NF-e 4.00: o Body recebe nfeDadosMsg diretamente.
old='''        string response = PostSoap(cert, url, ConsultWsNs, "nfeConsultaNF", ConsultWsNs + "/nfeConsultaNF", payload);'''
new='''        string response = PostProtocolSoap(cert, url, payload);'''
if old not in s: raise SystemExit('QueryProtocol antigo não encontrado')
s=s.replace(old,new,1)

# 2) Distribuição DF-e: cUFAutor é obrigatório no distDFeInt.
old='''        string payload = BuildDistributionPayload(key, cleanCnpj);'''
new='''        string payload = BuildDistributionPayload(key, cleanCnpj, GetAuthorCUF(cert, key));'''
if old not in s: raise SystemExit('BuildDistributionPayload call não encontrado')
s=s.replace(old,new,1)

old='''    private static string BuildDistributionPayload(string key, string cnpj)\n    {\n        return "<distDFeInt xmlns=\\\"" + NFeNs + "\\\" versao=\\\"1.01\\\"><tpAmb>1</tpAmb><CNPJ>" + Escape(cnpj) + "</CNPJ><consChNFe><chNFe>" + Escape(key) + "</chNFe></consChNFe></distDFeInt>";\n    }\n\n    private static string PostSoap(X509Certificate2 cert, string url, string wsNamespace, string operation, string action, string payload)\n    {\n        string body12 = "<?xml version=\\\"1.0\\\" encoding=\\\"utf-8\\\"?><soap12:Envelope xmlns:soap12=\\\"http://www.w3.org/2003/05/soap-envelope\\\"><soap12:Body><" + operation + " xmlns=\\\"" + wsNamespace + "\\\"><nfeDadosMsg>" + payload + "</nfeDadosMsg></" + operation + "></soap12:Body></soap12:Envelope>";\n        try { return SendSoap(cert, url, action, body12, true); }\n        catch (Exception first)\n        {\n            string body11 = "<?xml version=\\\"1.0\\\" encoding=\\\"utf-8\\\"?><soap:Envelope xmlns:soap=\\\"http://schemas.xmlsoap.org/soap/envelope/\\\"><soap:Body><" + operation + " xmlns=\\\"" + wsNamespace + "\\\"><nfeDadosMsg>" + payload + "</nfeDadosMsg></" + operation + "></soap:Body></soap:Envelope>";\n            try { return SendSoap(cert, url, action, body11, false); }\n            catch (Exception second) { throw new Exception("Falha no Web Service oficial: " + first.Message + " | fallback SOAP 1.1: " + second.Message); }\n        }\n    }\n'''
new='''    private static string BuildDistributionPayload(string key, string cnpj, string cufAutor)\n    {\n        return "<distDFeInt xmlns=\\\"" + NFeNs + "\\\" versao=\\\"1.01\\\"><tpAmb>1</tpAmb><cUFAutor>" + Escape(cufAutor) + "</cUFAutor><CNPJ>" + Escape(cnpj) + "</CNPJ><consChNFe><chNFe>" + Escape(key) + "</chNFe></consChNFe></distDFeInt>";\n    }\n\n    // NT 2016.002 / NF-e 4.00: nfeDadosMsg é o parâmetro raiz do SOAP Body.\n    // Não existe um wrapper <nfeConsultaNF> em torno dele.\n    private static string BuildProtocolEnvelope(string payload, bool soap12)\n    {\n        if (soap12)\n            return "<?xml version=\\\"1.0\\\" encoding=\\\"utf-8\\\"?><soap12:Envelope xmlns:xsi=\\\"http://www.w3.org/2001/XMLSchema-instance\\\" xmlns:xsd=\\\"http://www.w3.org/2001/XMLSchema\\\" xmlns:soap12=\\\"http://www.w3.org/2003/05/soap-envelope\\\"><soap12:Body><nfeDadosMsg xmlns=\\\"" + ConsultWsNs + "\\\">" + payload + "</nfeDadosMsg></soap12:Body></soap12:Envelope>";\n        return "<?xml version=\\\"1.0\\\" encoding=\\\"utf-8\\\"?><soap:Envelope xmlns:xsi=\\\"http://www.w3.org/2001/XMLSchema-instance\\\" xmlns:xsd=\\\"http://www.w3.org/2001/XMLSchema\\\" xmlns:soap=\\\"http://schemas.xmlsoap.org/soap/envelope/\\\"><soap:Body><nfeDadosMsg xmlns=\\\"" + ConsultWsNs + "\\\">" + payload + "</nfeDadosMsg></soap:Body></soap:Envelope>";\n    }\n\n    private static string PostProtocolSoap(X509Certificate2 cert, string url, string payload)\n    {\n        string action = ConsultWsNs + "/nfeConsultaNF";\n        try { return SendSoap(cert, url, action, BuildProtocolEnvelope(payload, true), true); }\n        catch (Exception first)\n        {\n            try { return SendSoap(cert, url, action, BuildProtocolEnvelope(payload, false), false); }\n            catch (Exception second) { throw new Exception("Falha no Web Service Consulta Protocolo: " + first.Message + " | fallback SOAP 1.1: " + second.Message); }\n        }\n    }\n\n    // A Distribuição DF-e tem contrato diferente: usa nfeDistDFeInteresse/nfeDadosMsg.\n    private static string PostSoap(X509Certificate2 cert, string url, string wsNamespace, string operation, string action, string payload)\n    {\n        string body12 = "<?xml version=\\\"1.0\\\" encoding=\\\"utf-8\\\"?><soap12:Envelope xmlns:xsi=\\\"http://www.w3.org/2001/XMLSchema-instance\\\" xmlns:xsd=\\\"http://www.w3.org/2001/XMLSchema\\\" xmlns:soap12=\\\"http://www.w3.org/2003/05/soap-envelope\\\"><soap12:Body><" + operation + " xmlns=\\\"" + wsNamespace + "\\\"><nfeDadosMsg>" + payload + "</nfeDadosMsg></" + operation + "></soap12:Body></soap12:Envelope>";\n        try { return SendSoap(cert, url, action, body12, true); }\n        catch (Exception first)\n        {\n            string body11 = "<?xml version=\\\"1.0\\\" encoding=\\\"utf-8\\\"?><soap:Envelope xmlns:xsi=\\\"http://www.w3.org/2001/XMLSchema-instance\\\" xmlns:xsd=\\\"http://www.w3.org/2001/XMLSchema\\\" xmlns:soap=\\\"http://schemas.xmlsoap.org/soap/envelope/\\\"><soap:Body><" + operation + " xmlns=\\\"" + wsNamespace + "\\\"><nfeDadosMsg>" + payload + "</nfeDadosMsg></" + operation + "></soap:Body></soap:Envelope>";\n            try { return SendSoap(cert, url, action, body11, false); }\n            catch (Exception second) { throw new Exception("Falha no Web Service Distribuição DF-e: " + first.Message + " | fallback SOAP 1.1: " + second.Message); }\n        }\n    }\n\n    private static string GetAuthorCUF(X509Certificate2 cert, string key)\n    {\n        string subject = cert == null ? "" : (cert.Subject ?? "");\n        string state = "";\n        Match m = Regex.Match(subject, @"(?:^|,\\s*)(?:S|ST)=([^,]+)", RegexOptions.IgnoreCase);\n        if (m.Success) state = (m.Groups[1].Value ?? "").Trim().ToUpperInvariant();\n        Dictionary<string,string> map = new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase)\n        {\n            {"RO","11"},{"AC","12"},{"AM","13"},{"RR","14"},{"PA","15"},{"AP","16"},{"TO","17"},\n            {"MA","21"},{"PI","22"},{"CE","23"},{"RN","24"},{"PB","25"},{"PE","26"},{"AL","27"},{"SE","28"},{"BA","29"},\n            {"MG","31"},{"ES","32"},{"RJ","33"},{"SP","35"},{"PR","41"},{"SC","42"},{"RS","43"},\n            {"MS","50"},{"MT","51"},{"GO","52"},{"DF","53"},\n            {"SAO PAULO","35"},{"SÃO PAULO","35"},{"MINAS GERAIS","31"},{"RIO DE JANEIRO","33"},{"RIO GRANDE DO SUL","43"},{"SANTA CATARINA","42"},{"PARANA","41"},{"PARANÁ","41"}\n        };\n        string cuf;\n        if (!String.IsNullOrEmpty(state) && map.TryGetValue(state, out cuf)) return cuf;\n        // Fallback conservador para integrações antigas que não publicam UF no JSON.\n        // A consulta protocolo continua correta; a distribuição poderá retornar rejeição explícita caso a UF do interessado seja distinta da UF da chave.\n        return key != null && key.Length >= 2 ? key.Substring(0,2) : "35";\n    }\n'''
if old not in s: raise SystemExit('Bloco SOAP antigo não localizado')
s=s.replace(old,new,1)

# 3) Rejeições de estrutura/SOAP não devem aparecer em verde como consulta bem-sucedida.
old='''        r.Ok = !String.IsNullOrEmpty(r.CStat) && r.CStat != "108" && r.CStat != "109";'''
new='''        r.Ok = r.CStat == "100" || r.CStat == "101" || r.CStat == "110" || r.CStat == "150" || r.CStat == "151" || r.CStat == "155" || r.CStat == "217" || r.CStat == "301" || r.CStat == "302";'''
if old not in s: raise SystemExit('Regra ProtocolResult.Ok não encontrada')
s=s.replace(old,new,1)

# 4) Self-test passa a validar exatamente os dois formatos de SOAP.
anchor='''        string body = BuildDistributionPayload(key, "12345678000199");\n        if (body.IndexOf("consChNFe", StringComparison.Ordinal) < 0 || body.IndexOf(key, StringComparison.Ordinal) < 0) return WriteError("Self-test: XML de distribuição incorreto.", 94);'''
replacement='''        string body = BuildDistributionPayload(key, "12345678000199", "35");\n        if (body.IndexOf("<cUFAutor>35</cUFAutor>", StringComparison.Ordinal) < 0 || body.IndexOf("consChNFe", StringComparison.Ordinal) < 0 || body.IndexOf(key, StringComparison.Ordinal) < 0) return WriteError("Self-test: XML de distribuição incorreto.", 94);\n        string pe = BuildProtocolEnvelope("<consSitNFe xmlns=\\\"" + NFeNs + "\\\" versao=\\\"4.00\\\"><tpAmb>1</tpAmb><xServ>CONSULTAR</xServ><chNFe>" + key + "</chNFe></consSitNFe>", true);\n        if (pe.IndexOf("<nfeDadosMsg xmlns=\\\"" + ConsultWsNs + "\\\">", StringComparison.Ordinal) < 0 || pe.IndexOf("<nfeConsultaNF", StringComparison.Ordinal) >= 0) return WriteError("Self-test: SOAP Consulta Protocolo incorreto.", 95);'''
if anchor not in s: raise SystemExit('Self-test antigo não encontrado')
s=s.replace(anchor,replacement,1)

s=s.rstrip()+"\n// "+MARK+" — SOAP NF-e 4.00 corrigido e cUFAutor incluído.\n"
p.write_text(s,encoding='utf-8',newline='\n')
print('3.12.1: SOAP Consulta Protocolo corrigido; Distribuição DF-e com cUFAutor; rejeições estruturais não são sucesso.')
